<?php $ZN = RecepcionesController::ZONAS; $DN = RecepcionesController::DANOS; $CK = RecepcionesController::CHECK; ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Acta de recepción #<?= $r['id'] ?></title>
<style>body{font-family:Arial,sans-serif;font-size:13px;max-width:780px;margin:20px auto;color:#111}h1{font-size:20px;margin:0}h3{font-size:13px;margin:14px 0 4px;border-bottom:1px solid #999;padding-bottom:2px;text-transform:uppercase}
table{width:100%;border-collapse:collapse}td{padding:3px 6px;border:1px solid #ccc}.ph img{height:90px;margin:2px;border:1px solid #ccc}.sig{margin-top:30px;display:flex;justify-content:space-between;text-align:center}.sig div{width:45%;border-top:1px solid #000;padding-top:4px}.sig img{max-height:70px;display:block;margin:0 auto}@media print{.np{display:none}}</style></head>
<body onload="window.print()"><div style="display:flex;justify-content:space-between"><div><h1><?= e($emp['nombre']) ?></h1><div><?= e($emp['direccion'] ?? '') ?> · <?= e($emp['telefono'] ?? '') ?></div></div><div style="text-align:right"><b>ACTA DE RECEPCIÓN #<?= $r['id'] ?></b><br><?= fdate($r['created_at'], true) ?></div></div>
<h3>Vehículo</h3><table><tr><td>Placa: <b><?= e($r['placa']) ?></b></td><td>Cliente: <?= e($r['cliente'] ?? '-') ?></td><td>Tel: <?= e($r['telefono'] ?? '-') ?></td></tr>
<tr><td>Vehículo: <?= e(trim(($r['marca'] ?? '') . ' ' . ($r['modelo'] ?? '') . ' ' . ($r['color'] ?? '')) ?: '-') ?></td><td>Km: <?= $r['kilometraje'] ? num($r['kilometraje'], 0) : '-' ?></td><td>Combustible: <?= (int)$r['combustible'] ?>%</td></tr></table>
<h3>Objetos que ingresan</h3><table><tr><?php $i = 0; foreach ($CK as $k => $l): ?><td><?= in_array($k, $r['check_l']) ? '☑' : '☐' ?> <?= $l ?></td><?php if (++$i % 3 == 0) echo '</tr><tr>'; endforeach; ?></tr></table>
<h3>Daños previos declarados</h3><?php if (!$r['danos_l']): ?><p>Sin daños declarados.</p><?php else: ?><table><?php foreach ($r['danos_l'] as $z => $t): ?><tr><td><?= e($ZN[$z] ?? $z) ?></td><td><?= e($DN[$t] ?? $t) ?></td></tr><?php endforeach; ?></table><?php endif; ?>
<?php if ($r['observaciones']): ?><h3>Observaciones</h3><p><?= e($r['observaciones']) ?></p><?php endif; ?>
<?php if ($r['fotos_l']): ?><h3>Fotos</h3><div class="ph"><?php foreach ($r['fotos_l'] as $f): ?><img src="<?= asset('uploads/recepciones/' . e($f)) ?>"><?php endforeach; ?></div><?php endif; ?>
<p style="font-size:11px;margin-top:14px">El cliente declara estar conforme con el estado del vehículo descrito al momento del ingreso.</p>
<div class="sig"><div><?php if ($r['firma']): ?><img src="<?= asset('uploads/recepciones/' . e($r['firma'])) ?>"><?php else: ?><br><br><?php endif; ?>Firma del cliente</div><div><br><br>Recibido por: <?= e($r['usuario'] ?? '') ?></div></div></body></html>
